1. Create a `StudyAwareViewport.js` wrapper component:
   ```javascript
   import React from 'react';
   import { useSelector } from 'react-redux';
   import { OHIFCornerstoneViewport } from '@ohif/extension-cornerstone';

   const StudyAwareViewport = (props) => {
     const viewportData = useSelector(state => state.viewports[props.viewportIndex]);
     const isCurrent = viewportData.StudyInstanceUID === props.currentStudyUID;

     const borderColor = isCurrent ? 'var(--color-primary)' : 'var(--color-warning)';

     return (
       <div style={{ border: `2px solid ${borderColor}` }}>
         <OHIFCornerstoneViewport {...props} />
       </div>
     );
   };
   ```
2. Override the default viewport component in the extension's `preRegistration` hook:
   ```javascript
   app.registerComponent({
     name: 'OHIFCornerstoneViewport',
     component: StudyAwareViewport
   });
   ```
