   const ViewportOverlay = ({ studyDate, borderColor }) => (
     <div className="viewport-overlay" style={{ color: borderColor }}>
       {/* existing overlay content */}
       <div className="study-date">{studyDate}</div>
     </div>
   );
   ```
4. Update the hanging protocol service to apply the new viewport component when multiple studies are loaded.

1. Create a `CustomDataSource.js` class extending `DICOMwebDataSource`:
   ```javascript
   import { DICOMwebDataSource } from '@ohif/extension-default';

   class CustomDataSource extends DICOMwebDataSource {
     async mapStudies(studies) {
       const mappedStudies = await super.mapStudies(studies);
       return mappedStudies.map(study => ({
         ...study,
         series: [
           {
             SeriesDescription: 'All Images',
             SeriesNumber: -1,
             instances: study.series.flatMap(s => s.instances),
             isVirtual: true
           },
           ...study.series
         ]
       }));
     }
   }
   ```
2. Register the `CustomDataSource` in your extension's `index.js`:
   ```javascript
   export default {
     id: 'myCustomExtension',
     // ...
     dataSourcesModule: {
       getDataSources: [CustomDataSource]
     }
   };
   ```
3. Update `app-config.js` to use the new data source:
   ```javascript
   dataSources: [
     {
       friendlyName: 'My Custom Data Source',
       namespace: '@myOrg/custom-datasource',
       sourceName: 'customDicomWeb',
       configuration: {
         // ... existing configuration ...
       }
     }
   ]
   ```
